    explanation: '顕熱比（SHF：Sensible Heat Factor）は顕熱量÷全熱量（顕熱＋潜熱）で定義される。SHFが小さい（0に近い）ほど潜熱負荷（湿度変化）の割合が大きく、除湿能力の大きいコイルが必要となる。空気線図上でSHFはコイルの処理過程の勾配を決める。SHFは顕熱量を全熱量（顕熱＋潜熱）で除した値であり、値が小さいほど潜熱すなわち除湿の割合が大きいことを意味する。一般事務室の冷房では0.85前後、人体潜熱の多い劇場や集会室では0.7前後、厨房では0.6程度となる。SHFが小さいほど低い装置露点が必要になる。\n\n【図解】室用途とSHFの目安\n　室用途｜SHFの目安｜処理の特徴\n　一般事務室｜0.85前後｜顕熱が主体\n　劇場・集会室｜0.7前後｜人体潜熱が大きい\n　厨房｜0.6程度｜除湿の比重が大きい\n　⇒ SHFが小さいほど全熱に占める除湿の割合が大きい\n　⚠ SHFが小さい＝顕熱が小さい、ではない。あくまで全熱に対する割合である。',
