    correctKey: 'B',
    explanation: 'CEC/AC（空調エネルギー消費係数）は省エネ法の建築物評価指標の一つで、年間実際の空調エネルギー消費量を年間仮想空調エネルギー消費量で除した値。1.0未満で基準適合。小さいほど省エネ性能が高いことを示す。CEC/ACは、年間の実際の空調エネルギー消費量を仮想的な標準の消費量で除した無次元の値で、値が小さいほど省エネ性能が高い。現行の建築物省エネ法では一次エネルギー消費量の基準比であるBEIに置き換えられているが、基準値に対する比で評価するという考え方は共通している。\n\n【図解】省エネ性能の評価指標\n　指標｜内容｜望ましい方向\n　CEC/AC｜空調の年間消費量÷標準値｜小さいほど良い\n　BEI｜設計一次エネ÷基準一次エネ｜小さいほど良い\n　PAL*｜外皮の年間熱負荷｜小さいほど良い\n　⇒ いずれも基準に対する比であり、1.0以下であることが求められる\n　⚠ 絶対量ではなく比である。規模の異なる建物を比較できるのが利点である。',
