    correctKey: 'A',
    explanation: 'トレーサーガス法は室内にSF₆・CO₂などの指示物質（トレーサーガス）を注入しその濃度変化を時間的に追跡することで実際の換気量・換気回数・空気齢などを実測する方法である。設計値と実際の換気性能の乖離を確認するのに有効な手法。トレーサーガス法は、SF₆やCO₂などのガスを室内に放出し、その濃度変化から換気量を実測する方法である。濃度減衰法、定常濃度法、定量注入法があり、隙間風や気流の影響を含めた実際の換気量を把握できる。設計値との差の確認のほか、換気効率や空気齢の測定にも用いられる。\n\n【図解】トレーサーガス法の種類\n　手法｜方法｜特徴\n　濃度減衰法｜一定量を放出し減衰を測る｜最も一般的\n　定常濃度法｜一定量を連続放出する｜長時間の平均を把握\n　定量注入法｜濃度が一定になるよう注入｜大空間に適する\n　⇒ 実際の建物での換気量を実測できる点が利点\n　⚠ 設計換気量と実換気量は一致しない。隙間や気流の影響を含むためである。',
